changes.old:
for parent in cfg["parent_order"]:
        decision=read(root/"decisions"/(parent+"_FINAL.json"))
        require(decision.get("complete") is True,"2b存在未结项设计")

changes.new:
closed=[parent for parent in cfg["parent_order"] if (root/"decisions"/(parent+"_FINAL.json")).exists()]
    require(0<len(closed)<22 and closed==cfg["parent_order"][:len(closed)],"必须是严格的已完成前缀")
    for parent in closed:
        decision=read(root/"decisions"/(parent+"_FINAL.json"))
        require(decision.get("complete") is True,"已启动设计未结项")
    for parent in cfg["parent_order"][len(closed):]:
        for ordinal in range(1,4):
            case=parent+f"__T{ordinal}"
            w=root/cfg["case_paths"][case]
            require(not any((w/x).exists() for x in ("worker_started.json","done.json","failure.txt","launch_claim.json")),"未开始设计有运行标记："+case)
